func:
// ============================================================
// 1 · PLAN INLEZEN
// Leest de EMHASS-publish-sensoren uit de HA global context en zet
// elke reeks om naar { tijdstempel: getal }. Schrijft niets.
// Configuratie: dubbelklik het tabblad → Environment variables.
// ============================================================
const E = (k, d) => { const v = env.get(k); return (v === undefined || v === null || v === '') ? d : v; };
function haStates() {
    const ha = global.get('homeassistant'); if (!ha) return {};
    const srv = ha.homeAssistant || Object.values(ha)[0];
    return (srv && srv.states) || {};
}

const ENT = {
    soc:    E('ENT_FC_SOC',   'sensor.soc_batt_forecast'),
    batt:   E('ENT_FC_BATT',  'sensor.p_batt_forecast'),
    grid:   E('ENT_FC_GRID',  'sensor.p_grid_forecast'),
    load:   E('ENT_FC_LOAD',  'sensor.p_load_forecast'),
    pv:     E('ENT_FC_PV',    'sensor.p_pv_forecast'),
    socNow: E('ENT_BATT_SOC', 'sensor.deye_battery_soc'),
};
// EMHASS zet de reeks in een attribuut; bekende namen eerst, anders het eerste array met 'date'
const PREFERRED = ['battery_scheduled_soc', 'battery_scheduled_power', 'forecasts'];

function seriesOf(entity) {
    const out = {};
    const a = entity && entity.attributes;
    if (!a) return out;
    let arr = null;
    for (const k of PREFERRED) if (Array.isArray(a[k])) { arr = a[k]; break; }
    if (!arr) arr = Object.values(a).find(v => Array.isArray(v) && v.length && v[0] && v[0].date !== undefined) || [];
    for (const it of arr) {
        if (!it || it.date === undefined) continue;
        const k = Object.keys(it).find(x => x !== 'date' && it[x] !== null && it[x] !== '' && Number.isFinite(Number(it[x])));
        if (k) out[it.date] = Number(it[k]);
    }
    return out;
}

const S = haStates();
const series = {};
const missing = [];
for (const key of ['soc', 'batt', 'grid', 'load', 'pv']) {
    series[key] = seriesOf(S[ENT[key]]);
    if (!Object.keys(series[key]).length) missing.push(ENT[key]);
}

// soc, batt en grid zijn nodig; load en pv alleen voor de PV-laadclassificatie
const missingReq = missing.filter(e => [ENT.soc, ENT.batt, ENT.grid].includes(e));
if (missingReq.length) {
    node.status({ fill: 'red', shape: 'ring', text: `geen data: ${missingReq.join(', ')}` });
    node.warn(`Plan onvolledig, cyclus overgeslagen. Ontbrekend: ${missingReq.join(', ')}`);
    return null;
}

// Gemeten SOC heeft voorkeur; anders de state van de SOC-forecastsensor
let currentSoc = parseFloat(S[ENT.socNow] && S[ENT.socNow].state);
if (!Number.isFinite(currentSoc)) currentSoc = parseFloat(S[ENT.soc] && S[ENT.soc].state);

msg.payload = { series, current_soc: Number.isFinite(currentSoc) ? currentSoc : null };
node.status({
    fill: missing.length ? 'yellow' : 'green', shape: 'dot',
    text: `${Object.keys(series.batt).length} kwartieren` + (missing.length ? ` (zonder ${missing.join(', ')})` : '')
});
return msg;

// ============================================================
// 2 · CLASSIFICEREN + SEGMENTEREN
// Per kwartier: wat wil EMHASS met de accu (charge / discharge / sell / hold)
// en waar komt de energie vandaan. Opeenvolgende gelijke kwartieren worden
// segmenten; het segment van het stuurkwartier gaat door naar stap 3.
// Tekens (EMHASS): p_batt > 0 = ontladen, p_grid > 0 = import.
// ============================================================
const E = (k, d) => { const v = env.get(k); return (v === undefined || v === null || v === '') ? d : v; };
const N = (k, d) => { const v = Number(E(k, d)); return Number.isFinite(v) ? v : d; };

const CFG = {
    deadband: N('DEADBAND_W', 100),        // |p| hieronder telt als 0
    maxChargeW: N('MAX_CHARGE_W', 5000),   // laden boven 90% hiervan = 'max_charge'
    tolerance: N('PV_TOLERANCE_W', 250),   // marge bij vergelijken laadvermogen met PV-surplus
    leadS: N('CONTROL_LEAD_S', 90),        // zoveel s vóór een kwartier begint, geldt dat kwartier al
    tz: E('TZ_NAME', 'Europe/Amsterdam'),
};
const Q = 15 * 60000;
const P = msg.payload || {};
const S = P.series || {};

const num = v => (v === undefined || v === null || v === '' || !Number.isFinite(Number(v))) ? null : Number(v);
// Op epoch-ms, zodat notatieverschillen tussen sensoren niet uitmaken
const byMs = obj => {
    const r = {};
    for (const [k, v] of Object.entries(obj || {})) { const t = Date.parse(k); if (Number.isFinite(t)) r[t] = v; }
    return r;
};
const ser = { batt: byMs(S.batt), grid: byMs(S.grid), load: byMs(S.load), pv: byMs(S.pv), soc: byMs(S.soc) };
const allMs = [...new Set([...Object.keys(ser.batt), ...Object.keys(ser.grid), ...Object.keys(ser.soc)].map(Number))]
    .sort((a, b) => a - b);
const hhmm = t => new Intl.DateTimeFormat('nl-NL', { timeZone: CFG.tz, hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).format(new Date(t));

// ---------------------------------------------------------------- per kwartier
const points = allMs.map(t => {
    const p = {
        t, timestamp: new Date(t).toISOString(),
        p_batt: num(ser.batt[t]), p_grid: num(ser.grid[t]), p_load: num(ser.load[t]),
        p_pv: num(ser.pv[t]), p_soc: num(ser.soc[t]),
    };
    const charging    = p.p_batt !== null && p.p_batt < -CFG.deadband;
    const discharging = p.p_batt !== null && p.p_batt >  CFG.deadband;
    const importing   = p.p_grid !== null && p.p_grid >  CFG.deadband;
    const exporting   = p.p_grid !== null && p.p_grid < -CFG.deadband;
    const chargeW = charging ? -p.p_batt : 0;
    const pvSurplus = (p.p_pv !== null && p.p_load !== null) ? Math.max(0, p.p_pv - p.p_load) : null;

    p.intent = charging ? 'charge' : discharging ? (exporting ? 'sell' : 'discharge') : 'hold';
    p.charge_mode = charging ? (chargeW >= CFG.maxChargeW * 0.9 ? 'max_charge' : 'normal_charge') : 'none';
    p.charge_source = !charging ? 'none' : importing ? ((p.p_pv || 0) > CFG.deadband ? 'pv_and_grid' : 'grid') : 'pv';
    p.grid_direction = importing ? 'import' : exporting ? 'export' : 'none';
    p.grid_charge = charging && importing;
    p.grid_sell = discharging && exporting;
    p.discharge_partial = discharging && importing;   // accu levert een deel, de rest komt bewust uit het net

    // Alleen bij laden uit PV: hoeveel van het surplus gaat naar de accu?
    p.pv_charge_mode = 'none';
    if (charging && p.charge_source === 'pv') {
        if (pvSurplus === null) p.pv_charge_mode = 'unknown';
        else if (!exporting) p.pv_charge_mode = 'all_available';               // alles in de accu
        else if (p.charge_mode === 'max_charge') p.pv_charge_mode = 'excess_export'; // accu vol open, rest export
        else if (chargeW + CFG.tolerance < pvSurplus) p.pv_charge_mode = 'limited';  // bewust minder laden, meer export
        else p.pv_charge_mode = 'unknown';
    }
    return p;
});

// ---------------------------------------------------------------- smoothing
// Eén los hold-kwartier tussen twee gelijke charge/discharge-kwartieren is meestal een
// solver-artefact. Sell bewust uitgesloten. Het vermogen blijft dat van het kwartier zelf.
const COPY = ['intent', 'charge_mode', 'charge_source', 'pv_charge_mode', 'grid_direction',
              'grid_charge', 'grid_sell', 'discharge_partial'];
const smooth = (target, src) => {
    target.raw_intent = target.intent;
    for (const k of COPY) target[k] = src[k];
    target.smoothed = true;
};
const lastIntent = flow.get('last_intent');
if (points.length >= 2 && points[0].intent === 'hold'
    && ['charge', 'discharge'].includes(lastIntent) && points[1].intent === lastIntent) {
    smooth(points[0], points[1]);   // eerste kwartier heeft geen 'vorige' in de reeks
}
for (let i = 1; i < points.length - 1; i++) {
    const prev = points[i - 1], cur = points[i], next = points[i + 1];
    if (cur.intent === 'hold' && prev.intent === next.intent && ['charge', 'discharge'].includes(prev.intent)) {
        smooth(cur, prev);
    }
}

// ---------------------------------------------------------------- segmenten
const KEYS = ['intent', 'charge_mode', 'charge_source', 'pv_charge_mode', 'grid_direction'];
const avg = vals => { vals = vals.filter(Number.isFinite); return vals.length ? vals.reduce((a, b) => a + b, 0) / vals.length : null; };
const segments = [];
let buf = [];
const flush = () => {
    if (!buf.length) return;
    const f = buf[0], l = buf[buf.length - 1];
    segments.push({
        start: f.timestamp, end: new Date(l.t + Q).toISOString(), start_ms: f.t, end_ms: l.t + Q,
        duration_minutes: buf.length * 15,
        intent: f.intent, charge_mode: f.charge_mode, charge_source: f.charge_source,
        pv_charge_mode: f.pv_charge_mode, grid_direction: f.grid_direction,
        grid_charge: f.grid_charge, grid_sell: f.grid_sell, discharge_partial: f.discharge_partial,
        avg_p_batt: avg(buf.map(p => p.p_batt)),
        end_soc: l.p_soc,
        contains_smoothed: buf.some(p => p.smoothed),
    });
    buf = [];
};
for (const p of points) {
    const prev = buf[buf.length - 1];
    if (prev && (p.t !== prev.t + Q || !KEYS.every(k => prev[k] === p[k]))) flush();   // ook splitsen bij gaten
    buf.push(p);
}
flush();

// ---------------------------------------------------------------- stuurkwartier
// Elke minuut draaien; een kwartier geldt vanaf CONTROL_LEAD_S seconden vóór het begin.
const nowMs = msg.control_now ? Date.parse(msg.control_now) : Date.now();
if (!Number.isFinite(nowMs)) { node.warn('control_now onleesbaar'); return null; }
const tCtl = Math.floor((nowMs + CFG.leadS * 1000) / Q) * Q;   // kwartiergrenzen: klopt voor hele-uur-tijdzones
const segment = segments.find(s => s.start_ms <= tCtl && s.end_ms > tCtl) || null;
const point = points.find(p => p.t === tCtl) || null;

if (!msg.control_now && segment) flow.set('last_intent', segment.intent);   // simulatie laat de staat ongemoeid

msg.payload = {
    control_ms: tCtl,
    control_time: new Date(tCtl).toISOString(),
    segment, point,
    current_soc: P.current_soc ?? null,
    segments, points,
};
node.status(segment
    ? { fill: 'green', shape: 'dot', text: `${hhmm(tCtl)} → ${segment.intent}${segment.pv_charge_mode !== 'none' ? '/' + segment.pv_charge_mode : ''} (${segments.length} segm.)` }
    : { fill: 'yellow', shape: 'ring', text: `${hhmm(tCtl)} → geen plan voor dit kwartier` });
return msg;

// ============================================================
// 3 · GEWENSTE STAND
// Vertaalt het stuurkwartier naar één gewenste remote-stand:
//   { on: false }                       -> native (TOU-basis: zelfverbruik / PV-laden)
//   { on: true, bmode: 'power', ... }   -> accu vast vermogen (hold = 0 W)
//   { on: true, bmode: 'power_soc', ...}-> vast vermogen tot doel-SOC (omvormer stopt zelf)
// power in % van W_PER_PCT; + = ontladen, - = laden.
// Uitgang 1 -> executor. Uitgang 2 -> debug (ook bij simulatie met msg.control_now).
// ============================================================
const E = (k, d) => { const v = env.get(k); return (v === undefined || v === null || v === '') ? d : v; };
const N = (k, d) => { const v = Number(E(k, d)); return Number.isFinite(v) ? v : d; };
const B = (k, d) => { const v = E(k, d); return typeof v === 'boolean' ? v : String(v).toLowerCase() === 'true'; };

const CFG = {
    wPerPct: N('W_PER_PCT', 120),               // W per % setpoint (Deye: nominaal vermogen / 100)
    maxPct: N('MAX_PCT', 42),                   // plafond setpoint; niet hoger dan de max in je registerdefinitie
    minPct: N('MIN_PCT', 1),                    // kleinere setpoints -> 0
    socMin: N('SOC_MIN', 15),                   // ondergrens bij ontladen via remote
    socMaxCharge: N('SOC_MAX_CHARGE', 95),      // bovengrens bij laden via remote
    sellMargin: N('SELL_MARGIN_PCT', 1),        // ontladen knijpt af vlak bij het doel -> doel iets lager
    holdViaRemote: B('HOLD_VIA_REMOTE', true),
    limitedPv: B('RC_LIMITED_PV', false),
    partialDischarge: B('RC_PARTIAL_DISCHARGE', false),
};
const clamp = (v, lo, hi) => Math.min(hi, Math.max(lo, v));
const r1 = v => Math.round(v * 10) / 10;

const P = msg.payload || {};
const seg = P.segment, pt = P.point;
const cur = Number.isFinite(P.current_soc) ? P.current_soc : null;
const OFF = why => ({ on: false, why });

function decide() {
    if (!seg || !pt) return OFF('geen plan voor dit kwartier → native');

    const pBatt = Number.isFinite(pt.p_batt) ? pt.p_batt : 0;
    let pct = r1(clamp(pBatt / CFG.wPerPct, -CFG.maxPct, CFG.maxPct));
    if (Math.abs(pct) < CFG.minPct) pct = 0;
    const W = Math.round(Math.abs(pct) * CFG.wPerPct);

    const endSoc = Number(seg.end_soc);
    const chargeTo = Number.isFinite(endSoc) ? clamp(Math.ceil(endSoc), CFG.socMin, CFG.socMaxCharge) : CFG.socMaxCharge;
    const dischargeTo = Number.isFinite(endSoc) ? clamp(Math.floor(endSoc) - CFG.sellMargin, CFG.socMin, 100) : CFG.socMin;

    const idle = why => CFG.holdViaRemote
        ? { on: true, bmode: 'power', power: 0, soc: null, why }
        : OFF(why + ' → native');
    const charge = (label) => (cur !== null && cur >= chargeTo)
        ? idle(`${label}: doel ${chargeTo}% al bereikt`)
        : { on: true, bmode: 'power_soc', power: pct, soc: chargeTo, why: `${label} ${W} W tot ${chargeTo}%` };
    const discharge = (label) => (cur !== null && cur <= dischargeTo)
        ? idle(`${label}: doel ${dischargeTo}% al bereikt`)
        : { on: true, bmode: 'power_soc', power: pct, soc: dischargeTo, why: `${label} ${W} W tot ${dischargeTo}%` };

    // Netladen
    if (seg.intent === 'charge' && seg.grid_charge) {
        return pct < 0 ? charge('netladen') : idle('netlaad-segment, dit kwartier 0 W');
    }
    // Verkopen
    if (seg.intent === 'sell') {
        return pct > 0 ? discharge('verkopen') : idle('verkoop-segment, dit kwartier 0 W');
    }
    // Hold
    if (seg.intent === 'hold') return idle('hold (accu 0 W)');

    // Optioneel: bewust minder PV laden dan beschikbaar (rest export)
    if (seg.intent === 'charge' && seg.pv_charge_mode === 'limited' && CFG.limitedPv && pct < 0) {
        return charge('begrensd PV-laden');
    }
    // Optioneel: accu levert een deel van de load, rest bewust uit het net
    if (seg.intent === 'discharge' && seg.discharge_partial && CFG.partialDischarge && pct > 0) {
        return discharge('deel-ontladen');
    }

    const sub = seg.pv_charge_mode && seg.pv_charge_mode !== 'none' ? '/' + seg.pv_charge_mode
              : seg.discharge_partial ? '/partial' : '';
    return OFF(`${seg.intent}${sub} → native`);
}

const desired = decide();
const simulate = !!msg.control_now;

const summary = {
    control_time: P.control_time, simulate,
    intent: seg ? seg.intent : null, p_batt: pt ? pt.p_batt : null, p_grid: pt ? pt.p_grid : null,
    end_soc: seg ? seg.end_soc : null, current_soc: cur, desired,
};
// Plan publiceren voor andere flows (dashboards, eigen uitbreidingen)
if (!simulate) global.set(`${E('STATE_PREFIX', 'rc')}_plan`, Object.assign({ ts: Date.now(), segment: seg || null }, summary));

node.status({
    fill: desired.on ? 'green' : 'blue', shape: simulate ? 'ring' : 'dot',
    text: `${simulate ? '[SIM] ' : ''}${desired.on ? 'remote' : 'native'} | ${desired.why}`
});

if (simulate) return [null, { payload: summary, topic: 'simulatie' }];
return [{ topic: 'plan', desired }, { payload: summary, topic: 'plan' }];

// ============================================================
// 4 · REMOTE EXECUTOR — Deye Remote Control (registers 1100+, RAM)
// Ingangen:
//   topic 'plan'     gewenste stand uit stap 3
//   topic 'tick'     elke 5 s: reconcile + keepalive + verouderingscheck
//   topic 'enable' / 'disable'   handmatige schakelaar
// Uitgang 1: HA service call (alleen als DRY_RUN = false)
// Uitgang 2: DRY_RUN-log (wat er geschreven zóu worden)
//
// Principe: native (TOU) is de basis. Remote alleen voor afwijkingen.
// Valt Node-RED of HA weg, dan loopt de watchdog af en valt de Deye terug op native.
// Maximaal één write per tick, in vaste volgorde, met read-back vóór de volgende stap.
// ============================================================
const E = (k, d) => { const v = env.get(k); return (v === undefined || v === null || v === '') ? d : v; };
const N = (k, d) => { const v = Number(E(k, d)); return Number.isFinite(v) ? v : d; };
const B = (k, d) => { const v = E(k, d); return typeof v === 'boolean' ? v : String(v).toLowerCase() === 'true'; };
function haStates() {
    const ha = global.get('homeassistant'); if (!ha) return {};
    const srv = ha.homeAssistant || Object.values(ha)[0];
    return (srv && srv.states) || {};
}

const ENT = {
    mode:  E('RC_ENT_MODE',      'select.deye_rc_mode'),          // 1100
    wd:    E('RC_ENT_WATCHDOG',  'number.deye_rc_watchdog'),      // 1101
    side:  E('RC_ENT_SIDE',      'select.deye_rc_side'),          // 1104
    bmode: E('RC_ENT_BATT_MODE', 'select.deye_rc_battery_mode'),  // 1105
    power: E('RC_ENT_POWER',     'number.deye_rc_battery_power'), // 1109
    soc:   E('RC_ENT_SOC',       'number.deye_rc_soc'),           // 1110
};
const OPT = {
    on:     E('RC_OPT_ON',        'On'),
    off:    E('RC_OPT_OFF',       'Off'),
    side:   E('RC_OPT_SIDE_BATT', 'Battery'),
    power:  E('RC_OPT_POWER',     'Power'),
    powerSoc: E('RC_OPT_POWER_SOC', 'Power+SOC'),
};
const BMODE = { power: OPT.power, power_soc: OPT.powerSoc };
const CFG = {
    wd: N('RC_WATCHDOG_S', 300),
    keepaliveMs: N('RC_KEEPALIVE_S', 60) * 1000,
    resendMs: N('RC_RESEND_S', 15) * 1000,
    staleMs: N('PLAN_STALE_MIN', 10) * 60000,
    wPerPct: N('W_PER_PCT', 120),
    dry: B('DRY_RUN', true),
};

const now = Date.now();
const S = haStates();
// In DRY_RUN houden we een gesimuleerde stand bij, zodat de log de echte volgorde laat zien
const sim = CFG.dry ? (context.get('sim') || {}) : null;

function st(id) {
    if (sim && Object.prototype.hasOwnProperty.call(sim, id)) return String(sim[id]);
    const s = S[id]; return s ? s.state : undefined;
}
function num(id) { const v = parseFloat(st(id)); return Number.isFinite(v) ? v : null; }
function same(id, want) {
    const got = st(id);
    if (id.startsWith('select.')) return got === String(want);
    return Math.abs(parseFloat(got) - Number(want)) < 0.051;
}
function svc(id, value) {
    const domain = id.split('.')[0], isSel = domain === 'select';
    const service = isSel ? 'select_option' : 'set_value';
    return { payload: { action: `${domain}.${service}`, domain, service, target: { entity_id: [id] },
                        data: isSel ? { option: String(value) } : { value: Number(value) } },
             topic: id };
}

// ---------------------------------------------------------------- dispatcher
const topic = String(msg.topic || '');
if (flow.get('rc_enabled') === undefined) flow.set('rc_enabled', B('RC_ENABLED_AT_START', false));
if (topic === 'enable')  { flow.set('rc_enabled', true);  node.warn('Remote executor AAN'); }
if (topic === 'disable') { flow.set('rc_enabled', false); node.warn('Remote executor UIT'); }
if (topic === 'plan' && msg.desired) context.set('desired', Object.assign({}, msg.desired, { planTs: now }));

const PREFIX = E('STATE_PREFIX', 'rc');
const enabled = flow.get('rc_enabled') === true;
// Hook voor eigen logica (bijv. balanceren/rebulk via de BMS): zet global <prefix>_inhibit
// op een tekst of true, en de executor laat de Deye native tot je hem weer leegmaakt.
const inhibit = global.get(`${PREFIX}_inhibit`);
let des = context.get('desired') || { on: false, why: 'nog geen plan' };
if (!enabled) des = { on: false, why: 'executor uit' };
else if (inhibit) des = { on: false, why: `geblokkeerd: ${inhibit === true ? 'inhibit' : inhibit}` };
else if (des.on && now - (des.planTs || 0) > CFG.staleMs) des = { on: false, why: 'plan verouderd → native' };

// Live: zonder alle RC-entiteiten in HA niets schrijven.
// DRY_RUN mag wél doorlopen (handig vóór de registers bestaan); ontbrekende mode telt dan als 'uit'.
const missing = Object.values(ENT).filter(id => S[id] === undefined);
if (CFG.dry && st(ENT.mode) === undefined) { sim[ENT.mode] = OPT.off; context.set('sim', sim); }
if (!CFG.dry && missing.length) {
    node.status({ fill: 'red', shape: 'ring', text: `entiteit ontbreekt: ${missing[0]}${missing.length > 1 ? ` (+${missing.length - 1})` : ''}` });
    return null;
}

// ---------------------------------------------------------------- reconcile (max. 1 write per tick)
function reconcile(d) {
    const sent = context.get('sent') || {};
    const fresh = (id, v) => sent[id] && sent[id].v === v && now - sent[id].t < CFG.resendMs;
    const send = (id, v) => {
        sent[id] = { v, t: now }; context.set('sent', sent);
        if (CFG.dry) {
            sim[id] = v; context.set('sim', sim);
            return [null, { payload: `[DRY-RUN] ${id} → ${v}`, topic: 'dry_run', why: d.why }];
        }
        return [svc(id, v), null];
    };

    if (!d.on) {
        if (st(ENT.mode) !== OPT.off && !fresh(ENT.mode, OPT.off)) return send(ENT.mode, OPT.off);
        return null;
    }
    // volgorde: 1104 -> 1105 -> 1110 -> 1109 -> 1101 -> 1100 (nooit aan in AC-modus)
    const steps = [[ENT.side, OPT.side], [ENT.bmode, BMODE[d.bmode]]];
    if (d.soc !== null && d.soc !== undefined) steps.push([ENT.soc, d.soc]);
    steps.push([ENT.power, d.power]);
    for (const [id, v] of steps) {
        if (!same(id, v)) return fresh(id, v) ? null : send(id, v);   // wacht op read-back
    }
    if (st(ENT.mode) !== OPT.on) {
        const wdOk = Math.abs((num(ENT.wd) ?? -1) - CFG.wd) <= 1;
        if (!wdOk) return fresh(ENT.wd, CFG.wd) ? null : send(ENT.wd, CFG.wd);
        if (!fresh(ENT.mode, OPT.on)) { context.set('lastKa', now); return send(ENT.mode, OPT.on); }
        return null;
    }
    // keepalive: watchdog herschrijven; wisselende waarde garandeert een echte write
    if (now - (context.get('lastKa') || 0) >= CFG.keepaliveMs) {
        const k = !context.get('kaToggle'); context.set('kaToggle', k);
        context.set('lastKa', now);
        return send(ENT.wd, k ? CFG.wd + 1 : CFG.wd);
    }
    return null;
}

const out = reconcile(des);

// ---------------------------------------------------------------- status
const active = st(ENT.mode) === OPT.on;
